def build_directory_listing(
    self, path, filenames, filesystem_path, add_trailing_slash=False
):
    files = []
    dirs = []

    for filename in filenames:
        if filesystem_path:
            this_filesystem_path = os.path.join(filesystem_path, filename)
        else:
            this_filesystem_path = self.files[filename]

        is_dir = os.path.isdir(this_filesystem_path)

        if is_dir:
            if add_trailing_slash:
                dirs.append(
                    {
                        "link": os.path.join(f"/{path}", quote(filename), ""),
                        "basename": filename,
                    }
                )
            else:
                dirs.append(
                    {
                        "link": os.path.join(f"/{path}", quote(filename)),
                        "basename": filename,
                    }
                )
        else:
            size = os.path.getsize(this_filesystem_path)
            size_human = self.common.human_readable_filesize(size)
            files.append(
                {
                    "link": os.path.join(f"/{path}", quote(filename)),
                    "basename": filename,
                    "size_human": size_human,
                }
            )

    return files, dirs

